def is_decimal(s: str) -> bool:
    pattern = r'^[+-]?(\d*)\.\d{2}$'
    return bool(re.match(pattern, s))

def is_Two_Alter(s: str) -> bool:
    # Check length and distinct character count
    if len(s) < 2:
        return False
    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    # Check alternating pattern: s[0] != s[1], and every even index equals s[0], every odd index equals s[1]
    first_char = s[0]
    second_char = s[1]
    if first_char == second_char:
        return False

    for i, ch in enumerate(s):
        expected_char = first_char if i % 2 == 0 else second_char
        if ch != expected_char:
            return False
    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0

    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

def double_the_difference(lst):
    '''
    Given a list of numbers, return the sum of squares of the numbers
    in the list that are odd. Ignore numbers that are negative or not integers.
    '''
    return sum(x*x for x in lst if isinstance(x, int) and x > 0 and x % 2 == 1)

