def cycpattern_check(a, b):
    if not b:
        return True
    if len(b) > len(a):
        return False
    # Create the doubled string for rotation checking
    doubled = b + b
    # Check each rotation of b is substring of a
    for i in range(len(b)):
        rotation = doubled[i:i+len(b)]
        if rotation in a:
            return True
    return False

from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    results = []
    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [w for w in words if is_prime(len(w))]
    return " ".join(prime_length_words)

